        if (array_key_exists($keys[0], $arr)) $this->setDepartamentoId($arr[$keys[0]]);
        if (array_key_exists($keys[1], $arr)) $this->setPaisId($arr[$keys[1]]);
        if (array_key_exists($keys[2], $arr)) $this->setNombre($arr[$keys[2]]);
        if (array_key_exists($keys[3], $arr)) $this->setCodigoDane($arr[$keys[3]]);
