     *
     * @param                  Pais $v
     * @return Departamento The current object (for fluent API support)
     * @throws PropelException
     */
    public function setPais(Pais $v = null)
    {
        if ($v === null) {
            $this->setPaisId(NULL);
        } else {
            $this->setPaisId($v->getPaisId());
        }

        $this->aPais = $v;

        // Add binding for other direction of this n:n relationship.
        // If this object has already been added to the Pais object, it will not be re-added.
        if ($v !== null) {
            $v->addDepartamento($this);
        }


        return $this;
    }


    /**
