     * Avoids crafting an 'init[$relationName]s' method name
     * that wouldn't work when StandardEnglishPluralizer is used.
     *
     * @param string $relationName The name of the relation to initialize
     * @return void
     */
    public function initRelation($relationName)
    {
        if ('Ciudad' == $relationName) {
            $this->initCiudads();
        }
    }

    /**
     * Clears out the collCiudads collection
     *
     * This does not modify the database; however, it will remove any associated objects, causing
     * them to be refetched by subsequent calls to accessor method.
     *
     * @return Departamento The current object (for fluent API support)
     * @see        addCiudads()
     */
    public function clearCiudads()
    {
        $this->collCiudads = null; // important to set this to null since that means it is uninitialized
        $this->collCiudadsPartial = null;

        return $this;
    }

    /**
     * reset is the collCiudads collection loaded partially
     *
     * @return void
     */
    public function resetPartialCiudads($v = true)
    {
        $this->collCiudadsPartial = $v;
    }

    /**
     * Initializes the collCiudads collection.
     *
     * By default this just sets the collCiudads collection to an empty array (like clearcollCiudads());
     * however, you may wish to override this method in your stub class to provide setting appropriate
     * to your application -- for example, setting the initial array to the values stored in database.
     *
     * @param boolean $overrideExisting If set to true, the method call initializes
     *                                        the collection even if it is not empty
     *
     * @return void
     */
    public function initCiudads($overrideExisting = true)
    {
        if (null !== $this->collCiudads && !$overrideExisting) {
            return;
        }
        $this->collCiudads = new PropelObjectCollection();
        $this->collCiudads->setModel('Ciudad');
    }

    /**
     * Gets an array of Ciudad objects which contain a foreign key that references this object.
     *
     * If the $criteria is not null, it is used to always fetch the results from the database.
     * Otherwise the results are fetched from the database the first time, then cached.
     * Next time the same method is called without $criteria, the cached collection is returned.
     * If this Departamento is new, it will return
     * an empty collection or the current collection; the criteria is ignored on a new object.
     *
     * @param Criteria $criteria optional Criteria object to narrow the query
     * @param PropelPDO $con optional connection object
     * @return PropelObjectCollection|Ciudad[] List of Ciudad objects
     * @throws PropelException
     */
    public function getCiudads($criteria = null, PropelPDO $con = null)
    {
        $partial = $this->collCiudadsPartial && !$this->isNew();
        if (null === $this->collCiudads || null !== $criteria  || $partial) {
            if ($this->isNew() && null === $this->collCiudads) {
                // return empty collection
                $this->initCiudads();
            } else {
                $collCiudads = CiudadQuery::create(null, $criteria)
                    ->filterByDepartamento($this)
                    ->find($con);
                if (null !== $criteria) {
                    if (false !== $this->collCiudadsPartial && count($collCiudads)) {
                      $this->initCiudads(false);

                      foreach ($collCiudads as $obj) {
                        if (false == $this->collCiudads->contains($obj)) {
                          $this->collCiudads->append($obj);
                        }
                      }

                      $this->collCiudadsPartial = true;
                    }

                    $collCiudads->getInternalIterator()->rewind();

                    return $collCiudads;
                }

                if ($partial && $this->collCiudads) {
                    foreach ($this->collCiudads as $obj) {
                        if ($obj->isNew()) {
                            $collCiudads[] = $obj;
                        }
                    }
                }

                $this->collCiudads = $collCiudads;
                $this->collCiudadsPartial = false;
            }
        }

        return $this->collCiudads;
    }

    /**
     * Sets a collection of Ciudad objects related by a one-to-many relationship
     * to the current object.
     * It will also schedule objects for deletion based on a diff between old objects (aka persisted)
     * and new objects from the given Propel collection.
     *
     * @param PropelCollection $ciudads A Propel collection.
     * @param PropelPDO $con Optional connection object
     * @return Departamento The current object (for fluent API support)
     */
    public function setCiudads(PropelCollection $ciudads, PropelPDO $con = null)
    {
        $ciudadsToDelete = $this->getCiudads(new Criteria(), $con)->diff($ciudads);


        $this->ciudadsScheduledForDeletion = $ciudadsToDelete;

        foreach ($ciudadsToDelete as $ciudadRemoved) {
            $ciudadRemoved->setDepartamento(null);
        }

        $this->collCiudads = null;
        foreach ($ciudads as $ciudad) {
            $this->addCiudad($ciudad);
        }

        $this->collCiudads = $ciudads;
        $this->collCiudadsPartial = false;

        return $this;
    }

    /**
     * Returns the number of related Ciudad objects.
     *
     * @param Criteria $criteria
     * @param boolean $distinct
     * @param PropelPDO $con
     * @return int             Count of related Ciudad objects.
     * @throws PropelException
     */
    public function countCiudads(Criteria $criteria = null, $distinct = false, PropelPDO $con = null)
    {
        $partial = $this->collCiudadsPartial && !$this->isNew();
        if (null === $this->collCiudads || null !== $criteria || $partial) {
            if ($this->isNew() && null === $this->collCiudads) {
                return 0;
            }

            if ($partial && !$criteria) {
                return count($this->getCiudads());
            }
            $query = CiudadQuery::create(null, $criteria);
            if ($distinct) {
                $query->distinct();
            }

            return $query
                ->filterByDepartamento($this)
                ->count($con);
        }

        return count($this->collCiudads);
    }

    /**
     * Method called to associate a Ciudad object to this object
     * through the Ciudad foreign key attribute.
     *
     * @param    Ciudad $l Ciudad
     * @return Departamento The current object (for fluent API support)
     */
    public function addCiudad(Ciudad $l)
    {
        if ($this->collCiudads === null) {
            $this->initCiudads();
            $this->collCiudadsPartial = true;
        }

        if (!in_array($l, $this->collCiudads->getArrayCopy(), true)) { // only add it if the **same** object is not already associated
            $this->doAddCiudad($l);

            if ($this->ciudadsScheduledForDeletion and $this->ciudadsScheduledForDeletion->contains($l)) {
                $this->ciudadsScheduledForDeletion->remove($this->ciudadsScheduledForDeletion->search($l));
            }
        }

        return $this;
    }

    /**
     * @param	Ciudad $ciudad The ciudad object to add.
     */
    protected function doAddCiudad($ciudad)
    {
        $this->collCiudads[]= $ciudad;
        $ciudad->setDepartamento($this);
    }

    /**
     * @param	Ciudad $ciudad The ciudad object to remove.
     * @return Departamento The current object (for fluent API support)
     */
    public function removeCiudad($ciudad)
    {
        if ($this->getCiudads()->contains($ciudad)) {
            $this->collCiudads->remove($this->collCiudads->search($ciudad));
            if (null === $this->ciudadsScheduledForDeletion) {
                $this->ciudadsScheduledForDeletion = clone $this->collCiudads;
                $this->ciudadsScheduledForDeletion->clear();
            }
            $this->ciudadsScheduledForDeletion[]= clone $ciudad;
            $ciudad->setDepartamento(null);
        }

        return $this;
    }

    /**
     * Clears the current object and sets all attributes to their default values
     */
    public function clear()
    {
        $this->departamento_id = null;
        $this->pais_id = null;
        $this->nombre = null;
        $this->codigo_dane = null;
        $this->codigo = null;
        $this->alreadyInSave = false;
        $this->alreadyInValidation = false;
        $this->alreadyInClearAllReferencesDeep = false;
        $this->clearAllReferences();
        $this->resetModified();
        $this->setNew(true);
        $this->setDeleted(false);
    }

    /**
     * Resets all references to other model objects or collections of model objects.
     *
     * This method is a user-space workaround for PHP's inability to garbage collect
     * objects with circular references (even in PHP 5.3). This is currently necessary
     * when using Propel in certain daemon or large-volume/high-memory operations.
     *
     * @param boolean $deep Whether to also clear the references on all referrer objects.
     */
    public function clearAllReferences($deep = false)
    {
        if ($deep && !$this->alreadyInClearAllReferencesDeep) {
            $this->alreadyInClearAllReferencesDeep = true;
            if ($this->collCiudads) {
                foreach ($this->collCiudads as $o) {
                    $o->clearAllReferences($deep);
                }
            }
            if ($this->aPais instanceof Persistent) {
              $this->aPais->clearAllReferences($deep);
            }

            $this->alreadyInClearAllReferencesDeep = false;
        } // if ($deep)

        if ($this->collCiudads instanceof PropelCollection) {
            $this->collCiudads->clearIterator();
        }
        $this->collCiudads = null;
        $this->aPais = null;
    }

